    "question": "两弹一星表彰与精神？",
    "answer": "1999 年 9 月 18 日，江泽民同志在表彰为研制\"两弹一星\"作出突出贡献的科技专家大会上发表讲话，将\"两弹一星精神\"概括为\"热爱祖国、无私奉献，自力更生、艰苦奋斗，大力协同、勇于登攀\"24 个字。授予于敏、王大珩、王希季、朱光亚、孙家栋、任新民、吴自良、陈芳允、陈能宽、杨嘉墀、周光召、钱学森、屠守锷、黄纬禄、程开甲、彭桓武\"两弹一星\"功勋奖章；追授王淦昌、邓稼先、赵九章、姚桐斌、钱骥、钱三强、郭永怀\"两弹一星\"功勋奖章。",
