    "answer": "胸怀祖国、服务人民的爱国精神。在战争年代体现在科技救国，在如今新时代体现在科技强国，科学研究应面向国家重大需求。Eg：许多科学家如钱学森等出国留学，即便国外有很好的实验条件和待遇，但国内条件艰苦，仍克服阻碍回国；心得可用钱伟长先生的话：\"国家的需要，就是我的专业。\"",
