    "question": "怎样理解求实精神？",
    "answer": "追求真理、严谨治学的求实精神。科学是严谨的，不可弄虚作假；实践是检验真理的唯一标准，科学研究应从实践中来，到实践中去。求实是甘坐冷板凳的坚韧，是捍卫真理的胆魄。Eg：杂交水稻。",
