    "source": "感恩奖学金复习整合资料（资料+挖空试题）.docx · P234",
    "question": "科学无国界的理解？",
    "answer": "科学无国界：科学知识不受国界限制，且许多科学成果往往惠及全人类，成为共同的福祉。例如屠呦呦研制的青蒿素，使全球尤其是发展中国家疟疾患者摆脱病痛折磨，这样的科学成果对全人类都有深远意义。",
