    "question": "钱伟长的跨学科与育人事迹？",
    "answer": "第二，钱伟长被称为中国近代力学之父，但他除力学外，兼长应用数学、物理学、中文信息学等各个领域，且在科研过程中不畏困难和阻碍，得出很多创新性成果；同时非常关注教育，曾任清华大学副校长、上海大学校长等。这些都体现出他身上创新、求实、奉献、育人的科学家精神。",
