    "question": "钱伟长专业选择的启示？",
    "answer": "第三，我被他\"国家的需要，就是我的专业\"这句话深深感动。他刚考入清华的时候是语文和历史双满分，而物理只有 5 分，但在山河破碎、民族危亡的时代，他毅然转入物理系，最后以优异的成绩毕业，并且毕生都在为国家科技的发展做出贡献，体现了爱国精神。这也让我联想到了自己：虽然我现在的专业并非所谓的\"热门专业\"，但几年前的新冠让我们看到了（公共卫生/本专业领域）的重要性，因此我选择继续在这方面深造，希望未来能为国家相关事业发展贡献力量。",
